:root {
  --cyan: #62f3ff;
  --cyan-soft: #2bb9cc;
  --cyan-dim: #0e6b7a;
  --red: #ff5648;
  --gold: #ffc85a;
  --green: #74f7a8;
  --ink: #06131a;
  --ink-2: #0a1d27;
  --panel: rgba(5, 18, 26, 0.72);
  --line: rgba(110, 230, 255, 0.32);
  --font-display: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Roboto Condensed", Impact, sans-serif;
  --font-ui: "Bahnschrift", "DIN Alternate", "Segoe UI", Roboto, Arial, sans-serif;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #041015;
  color: #e9fbff;
  font-family: var(--font-ui);
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; cursor: crosshair; }
#game.locked { cursor: none; }

.hidden { display: none !important; }
button { font-family: inherit; color: inherit; }

/* ------------------------------------------------------------------ overlays */
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(1, 8, 12, 0.22) 74%, rgba(1, 6, 10, 0.72) 100%);
}
#damage-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 30; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(255, 44, 30, 0.55) 100%);
  box-shadow: inset 0 0 140px rgba(255, 30, 20, 0.65);
  transition: opacity 0.12s ease-out;
}
#damage-flash.on { opacity: 1; }
#damage-flash.low { opacity: 0.55; animation: lowhp 1.5s ease-in-out infinite; }
#speed-lines {
  position: absolute; inset: -18%; pointer-events: none; z-index: 3; opacity: 0;
  background: repeating-conic-gradient(from 0deg, transparent 0deg 5.4deg, rgba(140, 240, 255, 0.22) 5.55deg 5.75deg, transparent 5.9deg 10deg);
  -webkit-mask-image: radial-gradient(circle at center, transparent 0 35%, #000 72%);
  mask-image: radial-gradient(circle at center, transparent 0 35%, #000 72%);
  transition: opacity 0.35s ease;
  animation: speedspin 14s linear infinite;
}
#speed-lines.on { opacity: 0.75; }
#scanlines {
  position: absolute; inset: 0; pointer-events: none; z-index: 4; opacity: 0.18; mix-blend-mode: screen;
  background: repeating-linear-gradient(to bottom, rgba(160, 240, 255, 0.06) 0 1px, transparent 1px 3px);
}
@keyframes speedspin { to { transform: rotate(360deg); } }
@keyframes lowhp { 0%, 100% { opacity: 0.35; } 50% { opacity: 0.7; } }

/* ------------------------------------------------------------------ hud */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; opacity: 1; transition: opacity 0.3s; }
#hud.hidden { display: none; }

.panel {
  position: relative;
  background: linear-gradient(135deg, rgba(8, 26, 36, 0.86), rgba(4, 15, 22, 0.7));
  border: 1px solid rgba(100, 225, 255, 0.22);
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 13px 100%, 0 calc(100% - 13px));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.025), 0 0 26px rgba(0, 0, 0, 0.34);
  backdrop-filter: blur(5px);
}
.panel::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(135deg, rgba(98, 243, 255, 0.13), transparent 30%, transparent 75%, rgba(98, 243, 255, 0.06));
  clip-path: inherit;
}
.panel::after {
  content: ""; position: absolute; left: 0; top: 0; width: 46px; height: 2px; background: var(--cyan); opacity: 0.8;
}
kbd {
  display: inline-grid; place-items: center; min-width: 22px; height: 19px; padding: 0 5px;
  border: 1px solid rgba(130, 235, 255, 0.45); border-radius: 2px;
  background: rgba(5, 20, 28, 0.7); color: #d9fbff; font: 600 10px/1 var(--font-ui); letter-spacing: 0.08em;
  box-shadow: inset 0 -1px 0 rgba(98, 243, 255, 0.2);
}

/* player panel */
#player-panel {
  position: absolute; left: calc(22px + var(--safe-l)); top: calc(20px + var(--safe-t)); width: 322px;
  padding: 14px 16px 13px;
  animation: hud-in 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.id-row { display: flex; align-items: center; gap: 10px; }
.avatar {
  width: 40px; height: 40px; flex: 0 0 auto; color: var(--cyan); display: grid; place-items: center;
  background: radial-gradient(circle, rgba(98, 243, 255, 0.16), rgba(98, 243, 255, 0) 70%);
  border: 1px solid rgba(98, 243, 255, 0.34); clip-path: polygon(50% 0, 100% 24%, 100% 74%, 50% 100%, 0 74%, 0 24%);
}
.avatar svg { width: 28px; height: 28px; filter: drop-shadow(0 0 5px rgba(98, 243, 255, 0.7)); }
.id-text { flex: 1 1 auto; min-width: 0; }
.id-name { font: 700 15px/1.1 var(--font-display); letter-spacing: 0.14em; color: #f2fdff; white-space: nowrap; }
.id-name span { color: #6fb5c2; font-size: 9px; letter-spacing: 0.17em; }
.id-status { display: flex; gap: 5px; align-items: center; margin-top: 4px; font: 600 8px/1 var(--font-ui); letter-spacing: 0.2em; color: #83a9b2; }
.id-status i { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 6px var(--green); animation: pulse 1.7s infinite; }
.score { text-align: right; }
.score span { display: block; font: 600 7px/1 var(--font-ui); letter-spacing: 0.2em; color: #6d99a3; }
.score b { display: block; margin-top: 3px; font: 700 18px/1 var(--font-display); letter-spacing: 0.09em; color: var(--gold); text-shadow: 0 0 12px rgba(255, 200, 90, 0.35); }
.bar-row { margin-top: 9px; }
.bar-label { display: flex; justify-content: space-between; font: 600 8px/1 var(--font-ui); letter-spacing: 0.18em; color: #8fbcc5; margin-bottom: 4px; }
.bar-label b { color: #dffbff; font-size: 9px; }
.bar { position: relative; height: 8px; background: rgba(2, 12, 17, 0.9); border: 1px solid rgba(120, 210, 230, 0.18); overflow: hidden; }
.bar > div { position: absolute; inset: 1px; transform-origin: left center; transition: transform 0.18s ease; }
.bar.health > #hp-fill { background: linear-gradient(90deg, #ff3a2c, #ff7b44 60%, #ffb27b); box-shadow: 0 0 10px rgba(255, 70, 50, 0.6); }
.bar.energon > #en-fill { background: linear-gradient(90deg, #16a9c4, #62f3ff 70%, #c8fdff); box-shadow: 0 0 10px rgba(98, 243, 255, 0.5); }
.bar-ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 24px, rgba(2, 10, 14, 0.72) 24px 26px); }
.ability-row { display: flex; gap: 6px; margin-top: 11px; }
.ability {
  position: relative; flex: 1; height: 36px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  border: 1px solid rgba(98, 243, 255, 0.22); background: rgba(6, 24, 32, 0.6); overflow: hidden;
}
.ability .ab-glyph { font-size: 13px; line-height: 1; color: var(--cyan); }
.ability .ab-name { font: 600 6.5px/1 var(--font-ui); letter-spacing: 0.13em; color: #84b8c2; }
.ability .ab-cd { position: absolute; inset: 0; background: rgba(1, 8, 12, 0.78); transform-origin: bottom; transform: scaleY(0); pointer-events: none; }
.ability.locked { opacity: 0.38; filter: saturate(0.25); }
.ability.locked .ab-glyph { color: #8da1a6; }
.ability.ready { border-color: rgba(98, 243, 255, 0.5); box-shadow: inset 0 0 14px rgba(98, 243, 255, 0.12); }
.ability.active { border-color: var(--cyan); box-shadow: 0 0 12px rgba(98, 243, 255, 0.45), inset 0 0 16px rgba(98, 243, 255, 0.3); }
.ability.active .ab-glyph { color: #e3feff; text-shadow: 0 0 8px var(--cyan); }

/* minimap */
#map-panel {
  position: absolute; right: calc(22px + var(--safe-r)); top: calc(20px + var(--safe-t)); width: 232px; padding: 9px 10px 9px;
  animation: hud-in 0.7s 0.08s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.map-head { display: flex; justify-content: space-between; align-items: center; font: 700 9px/1 var(--font-ui); letter-spacing: 0.19em; color: #a7d3db; margin: 0 2px 7px; }
.map-head b { color: var(--cyan); font-size: 10px; }
.map-wrap { position: relative; width: 100%; aspect-ratio: 1; background: #041018; overflow: hidden; clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); }
#minimap { position: absolute; inset: 0; width: 100%; height: 100%; }
.map-ring { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(circle at center, transparent 48%, rgba(3, 14, 20, 0.32) 100%); box-shadow: inset 0 0 0 1px rgba(98, 243, 255, 0.24); }
.map-coords { position: absolute; left: 6px; bottom: 5px; font: 500 7px/1 var(--font-ui); letter-spacing: 0.13em; color: rgba(180, 240, 250, 0.65); text-shadow: 0 1px 2px #000; }
.map-foot { display: flex; align-items: center; justify-content: space-between; margin: 8px 2px 0; font: 600 8px/1 var(--font-ui); letter-spacing: 0.16em; color: #82aeb8; }
.map-foot b { color: #e9feff; font: 700 15px/1 var(--font-display); letter-spacing: 0.05em; }
.map-foot b i { color: #5f8b95; font-style: normal; font-size: 9px; margin: 0 2px; }

/* objective */
#objective-panel {
  position: absolute; right: calc(22px + var(--safe-r)); top: calc(329px + var(--safe-t)); width: 290px; padding: 12px 14px 11px;
  animation: hud-in 0.7s 0.16s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.obj-eyebrow { display: flex; align-items: center; gap: 6px; font: 600 8px/1 var(--font-ui); letter-spacing: 0.22em; color: var(--gold); }
.obj-eyebrow i { width: 14px; height: 1px; background: var(--gold); box-shadow: 0 0 6px var(--gold); }
.obj-title { margin-top: 6px; font: 700 14px/1.15 var(--font-display); letter-spacing: 0.08em; color: #f3feff; }
.obj-body { margin-top: 4px; font: 400 10px/1.5 var(--font-ui); color: #90b1b9; letter-spacing: 0.02em; }
.obj-progress { height: 3px; margin-top: 9px; background: rgba(2, 12, 17, 0.85); overflow: hidden; }
#obj-fill { height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold), #fff0b8); box-shadow: 0 0 10px rgba(255, 200, 90, 0.65); transition: width 0.35s ease; }
.obj-distance { display: flex; justify-content: space-between; margin-top: 6px; font: 600 8px/1 var(--font-ui); letter-spacing: 0.13em; color: #7faab4; }
#obj-distance { color: var(--cyan); }
#obj-hint { color: #5f8892; }

/* weapon */
#weapon-panel {
  position: absolute; left: calc(22px + var(--safe-l)); bottom: calc(22px + var(--safe-b)); width: 330px; height: 86px;
  display: flex; align-items: center; gap: 12px; padding: 12px 14px;
  animation: hud-in 0.7s 0.22s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.weapon-icon { width: 48px; height: 40px; flex: 0 0 auto; display: grid; place-items: center; color: var(--cyan); border-right: 1px solid rgba(98, 243, 255, 0.18); padding-right: 10px; }
.weapon-icon svg { width: 42px; height: 24px; filter: drop-shadow(0 0 6px rgba(98, 243, 255, 0.65)); }
.weapon-info { flex: 1 1 auto; min-width: 0; }
.weapon-name { font: 700 14px/1 var(--font-display); letter-spacing: 0.1em; color: #f1feff; }
.weapon-desc { margin-top: 4px; font: 500 7px/1.3 var(--font-ui); letter-spacing: 0.15em; color: #7fa8b1; }
.heat { position: relative; height: 4px; margin-top: 9px; background: rgba(2, 12, 17, 0.9); overflow: hidden; }
#heat-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #2cd6e8, #ffd45e 65%, #ff4d3d); transition: width 0.08s linear; }
.heat span { position: absolute; right: 0; top: -9px; font: 600 6px/1 var(--font-ui); letter-spacing: 0.2em; color: #5b8993; }
.weapon-slots { display: flex; flex-direction: column; gap: 4px; }
.slot { width: 18px; height: 18px; display: grid; place-items: center; font: 700 9px/1 var(--font-ui); color: #6f9aa3; border: 1px solid rgba(98, 243, 255, 0.18); background: rgba(5, 20, 27, 0.7); }
.slot.active { color: #06131a; background: var(--cyan); border-color: var(--cyan); box-shadow: 0 0 10px rgba(98, 243, 255, 0.5); }
.slot.locked { opacity: 0.35; }

/* crosshair */
#crosshair { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; transform: translate(-50%, -50%); pointer-events: none; transition: opacity 0.2s; }
#crosshair i { position: absolute; background: rgba(220, 250, 255, 0.88); box-shadow: 0 0 5px rgba(98, 243, 255, 0.8); transition: background 0.12s, transform 0.12s; }
#crosshair .ch-t { left: 50%; top: 2px; width: 1.5px; height: 9px; transform: translateX(-50%); }
#crosshair .ch-b { left: 50%; bottom: 2px; width: 1.5px; height: 9px; transform: translateX(-50%); }
#crosshair .ch-l { top: 50%; left: 2px; height: 1.5px; width: 9px; transform: translateY(-50%); }
#crosshair .ch-r { top: 50%; right: 2px; height: 1.5px; width: 9px; transform: translateY(-50%); }
#crosshair .ch-dot { left: 50%; top: 50%; width: 2.5px; height: 2.5px; border-radius: 50%; transform: translate(-50%, -50%); }
#crosshair.lock i { background: #ff6a58; box-shadow: 0 0 8px rgba(255, 70, 50, 0.9); }
#crosshair.lock { transform: translate(-50%, -50%) scale(0.82); }
.ch-lock { position: absolute; left: 50%; top: 48px; transform: translateX(-50%); font: 700 7px/1 var(--font-ui); letter-spacing: 0.22em; color: var(--red); opacity: 0; transition: opacity 0.15s; }
#crosshair.lock .ch-lock { opacity: 1; }
#crosshair.heat i { background: #ffb84d; }
#crosshair.disabled { opacity: 0; }
#hitmarker { position: absolute; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%, -50%) rotate(45deg); pointer-events: none; opacity: 0; }
#hitmarker i { position: absolute; background: #fff; box-shadow: 0 0 6px rgba(255, 255, 255, 0.9); }
#hitmarker i:nth-child(1) { left: 0; top: 50%; width: 8px; height: 1.5px; }
#hitmarker i:nth-child(2) { right: 0; top: 50%; width: 8px; height: 1.5px; }
#hitmarker i:nth-child(3) { top: 0; left: 50%; height: 8px; width: 1.5px; }
#hitmarker i:nth-child(4) { bottom: 0; left: 50%; height: 8px; width: 1.5px; }
#hitmarker.on { animation: hit 0.24s ease-out; }
#hitmarker.crit i { background: #ff5b46; box-shadow: 0 0 8px #ff3b28; }
@keyframes hit { 0% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(0.6); } 100% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(1.25); } }

/* boss */
#boss-bar { position: absolute; left: 50%; top: calc(24px + var(--safe-t)); width: min(560px, 44vw); transform: translateX(-50%); text-align: center; }
.boss-head { display: flex; justify-content: space-between; align-items: flex-end; font: 600 9px/1 var(--font-ui); letter-spacing: 0.24em; color: #ff8a7d; padding: 0 4px 6px; }
.boss-head b { font: 700 20px/0.85 var(--font-display); letter-spacing: 0.18em; color: #ffe9e6; text-shadow: 0 0 18px rgba(255, 60, 40, 0.55); }
.boss-track { position: relative; height: 10px; background: rgba(10, 4, 6, 0.85); border: 1px solid rgba(255, 84, 66, 0.5); clip-path: polygon(0 0, 100% 0, calc(100% - 7px) 100%, 7px 100%); overflow: hidden; }
#boss-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #8e130b, #ff4b36 55%, #ffb066); box-shadow: 0 0 16px rgba(255, 60, 40, 0.65); transition: width 0.18s; }
.boss-track i { position: absolute; top: 0; bottom: 0; width: 1px; background: rgba(10, 4, 6, 0.65); }
.boss-track i:nth-of-type(1) { left: 25%; } .boss-track i:nth-of-type(2) { left: 50%; } .boss-track i:nth-of-type(3) { left: 75%; }
.boss-sub { margin-top: 6px; font: 600 7px/1 var(--font-ui); letter-spacing: 0.2em; color: #a26360; }

/* banner */
#banner {
  position: absolute; left: 50%; top: 24%; transform: translate(-50%, 12px); text-align: center; opacity: 0; pointer-events: none;
  padding: 18px 44px 16px; min-width: 380px;
  background: linear-gradient(90deg, transparent, rgba(5, 24, 33, 0.9) 18%, rgba(5, 24, 33, 0.9) 82%, transparent);
  border-top: 1px solid rgba(98, 243, 255, 0.5); border-bottom: 1px solid rgba(98, 243, 255, 0.22);
  transition: opacity 0.25s, transform 0.35s cubic-bezier(0.2, 0.9, 0.2, 1);
}
#banner::before, #banner::after { content: ""; position: absolute; top: -1px; width: 1px; height: 100%; background: var(--cyan); box-shadow: 0 0 12px var(--cyan); }
#banner::before { left: 15px; } #banner::after { right: 15px; }
#banner.on { opacity: 1; transform: translate(-50%, 0); }
.banner-kicker { font: 600 8px/1 var(--font-ui); letter-spacing: 0.32em; color: var(--cyan); }
.banner-title { margin-top: 7px; font: 700 34px/1 var(--font-display); letter-spacing: 0.08em; color: #fff; text-shadow: 0 0 24px rgba(98, 243, 255, 0.45); }
.banner-desc { margin-top: 6px; font: 500 8px/1.4 var(--font-ui); letter-spacing: 0.22em; color: #8fbfc8; }

/* toast + prompt + feed */
#toast { position: absolute; left: 50%; bottom: calc(134px + var(--safe-b)); transform: translateX(-50%); display: flex; align-items: center; gap: 8px; padding: 7px 15px; background: rgba(3, 16, 22, 0.82); border-left: 2px solid var(--cyan); font: 600 9px/1 var(--font-ui); letter-spacing: 0.18em; color: #c9f7ff; opacity: 0; transition: opacity 0.22s; white-space: nowrap; }
#toast i { width: 5px; height: 5px; background: var(--cyan); transform: rotate(45deg); box-shadow: 0 0 7px var(--cyan); }
#toast.on { opacity: 1; }
#prompt { position: absolute; left: 50%; bottom: calc(190px + var(--safe-b)); transform: translateX(-50%); display: flex; gap: 8px; align-items: center; font: 600 9px/1 var(--font-ui); letter-spacing: 0.2em; color: #dffcff; padding: 7px 13px; background: rgba(3, 18, 24, 0.78); border: 1px solid rgba(98, 243, 255, 0.3); }
#feed { position: absolute; right: calc(22px + var(--safe-r)); top: 46%; width: 260px; display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.feed-item { font: 500 8.5px/1.3 var(--font-ui); letter-spacing: 0.1em; color: #9fc4cc; padding: 5px 9px; border-right: 1px solid rgba(98, 243, 255, 0.4); background: linear-gradient(90deg, transparent, rgba(4, 18, 25, 0.66)); text-align: right; animation: feedin 0.3s ease both; }
.feed-item b { color: var(--cyan); font-weight: 600; }
@keyframes feedin { from { opacity: 0; transform: translateX(10px); } to { opacity: 1; transform: none; } }

/* compass + mode + hints */
#compass { position: absolute; left: 50%; top: calc(16px + var(--safe-t)); transform: translateX(-50%); width: 300px; height: 26px; overflow: hidden; -webkit-mask-image: linear-gradient(90deg, transparent, #000 20%, #000 80%, transparent); mask-image: linear-gradient(90deg, transparent, #000 20%, #000 80%, transparent); opacity: 0.8; }
.compass-strip { position: absolute; inset: 0; display: flex; }
.compass-mark { position: absolute; left: 50%; top: 0; width: 1px; height: 7px; background: var(--cyan); box-shadow: 0 0 6px var(--cyan); }
#mode-tag { position: absolute; left: 50%; bottom: calc(126px + var(--safe-b)); transform: translateX(-50%); display: flex; gap: 7px; align-items: center; font: 600 8px/1 var(--font-ui); letter-spacing: 0.2em; color: #8fb9c1; }
#mode-tag .mode-dot { width: 6px; height: 6px; border: 1px solid var(--cyan); transform: rotate(45deg); background: rgba(98, 243, 255, 0.25); box-shadow: 0 0 7px rgba(98, 243, 255, 0.5); }
#mode-tag b { color: #d9fbff; font-weight: 600; }
#mode-tag.vehicle b { color: var(--gold); }
#mode-tag.vehicle .mode-dot { border-color: var(--gold); background: rgba(255, 200, 90, 0.3); box-shadow: 0 0 7px rgba(255, 200, 90, 0.55); }
#hint-bar { position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); display: flex; gap: 13px; align-items: center; font: 500 7.5px/1 var(--font-ui); letter-spacing: 0.12em; color: #6d99a2; }
#hint-bar span { display: flex; align-items: center; gap: 4px; }
#hint-bar kbd { height: 16px; min-width: 18px; font-size: 8px; }

#reticle-bracket { position: absolute; left: 50%; top: 50%; width: 70px; height: 70px; transform: translate(-50%, -50%); border: 1px solid rgba(255, 90, 70, 0.7); clip-path: polygon(0 0, 22% 0, 22% 2%, 2% 2%, 2% 22%, 0 22%, 0 0, 100% 0, 100% 22%, 98% 22%, 98% 2%, 78% 2%, 78% 0, 100% 0, 100% 100%, 78% 100%, 78% 98%, 98% 98%, 98% 78%, 100% 78%, 100% 100%, 0 100%, 0 78%, 2% 78%, 2% 98%, 22% 98%, 22% 100%, 0 100%); pointer-events: none; }

/* ------------------------------------------------------------------ touch */
#touch-ui { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
#joystick { position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(28px + var(--safe-b)); width: 132px; height: 132px; pointer-events: auto; touch-action: none; }
#joystick-ring { position: absolute; inset: 0; border: 1px solid rgba(98, 243, 255, 0.28); border-radius: 50%; background: radial-gradient(circle at center, rgba(5, 22, 29, 0.55), rgba(3, 14, 19, 0.22)); box-shadow: inset 0 0 24px rgba(98, 243, 255, 0.08); }
#joystick-stick { position: absolute; left: 50%; top: 50%; width: 56px; height: 56px; margin: -28px 0 0 -28px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(120, 246, 255, 0.4), rgba(10, 50, 62, 0.85) 70%); border: 1px solid rgba(140, 246, 255, 0.6); box-shadow: 0 0 18px rgba(98, 243, 255, 0.25), inset 0 0 12px rgba(98, 243, 255, 0.4); }
#joystick > span { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); font: 600 7px/1 var(--font-ui); letter-spacing: 0.24em; color: rgba(180, 240, 250, 0.5); }
#joystick-ring::before, #joystick-ring::after { content: ""; position: absolute; background: rgba(98, 243, 255, 0.3); }
#joystick-ring::before { left: 50%; top: 8px; width: 1px; height: 8px; box-shadow: 0 108px 0 rgba(98, 243, 255, 0.3); }
#joystick-ring::after { top: 50%; left: 8px; height: 1px; width: 8px; box-shadow: 108px 0 0 rgba(98, 243, 255, 0.3); }
#touch-buttons { position: absolute; right: calc(20px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); width: 220px; height: 190px; pointer-events: none; }
.tbtn {
  position: absolute; pointer-events: auto; touch-action: none; -webkit-tap-highlight-color: transparent;
  width: 58px; height: 58px; border-radius: 50%; display: grid; place-items: center; gap: 0;
  border: 1px solid rgba(98, 243, 255, 0.34); background: radial-gradient(circle at 35% 30%, rgba(29, 78, 92, 0.8), rgba(4, 18, 24, 0.7));
  box-shadow: inset 0 0 16px rgba(98, 243, 255, 0.09), 0 4px 18px rgba(0, 0, 0, 0.35); color: #c9f8ff;
}
.tbtn:active, .tbtn.down { transform: scale(0.94); border-color: var(--cyan); box-shadow: 0 0 18px rgba(98, 243, 255, 0.35), inset 0 0 20px rgba(98, 243, 255, 0.2); }
.tbtn .tb-ico { font-size: 18px; line-height: 1; color: var(--cyan); }
.tbtn .tb-lbl { font: 600 6.5px/1 var(--font-ui); letter-spacing: 0.12em; color: #8ab8c1; margin-top: 3px; }
.tbtn.fire { right: 0; bottom: 36px; width: 92px; height: 92px; border-width: 2px; background: radial-gradient(circle at 35% 30%, rgba(255, 100, 80, 0.3), rgba(30, 8, 8, 0.72)); border-color: rgba(255, 110, 85, 0.55); }
.tbtn.fire .tb-ico { font-size: 28px; color: #ff9a86; text-shadow: 0 0 12px rgba(255, 70, 50, 0.7); }
.tbtn.fire .tb-lbl { color: #d98f83; font-size: 7px; }
.tbtn.small { width: 56px; height: 56px; }
#btn-jump { right: 100px; bottom: 2px; }
#btn-transform { right: 8px; bottom: 138px; }
#btn-ability { right: 108px; bottom: 68px; width: 52px; height: 52px; }
#btn-weapon { right: 166px; bottom: 20px; width: 46px; height: 46px; }
#touch-ui .look-zone { position: absolute; right: 0; top: 0; width: 52%; height: 68%; pointer-events: auto; }

/* ------------------------------------------------------------------ start screen */
#start-screen {
  position: absolute; inset: 0; z-index: 40; overflow: hidden;
  background:
    linear-gradient(90deg, rgba(2, 10, 14, 0.92) 0%, rgba(2, 10, 14, 0.55) 42%, rgba(2, 10, 14, 0.14) 70%, rgba(2, 10, 14, 0.5) 100%),
    linear-gradient(0deg, rgba(2, 9, 12, 0.92) 0%, transparent 32%, transparent 67%, rgba(2, 9, 12, 0.75) 100%);
  transition: opacity 0.65s ease, visibility 0.65s;
}
#start-screen.leaving { opacity: 0; visibility: hidden; pointer-events: none; }
.start-grid { position: absolute; inset: 0; opacity: 0.2; pointer-events: none; background-image: linear-gradient(rgba(98, 243, 255, 0.12) 1px, transparent 1px), linear-gradient(90deg, rgba(98, 243, 255, 0.1) 1px, transparent 1px); background-size: 72px 72px; -webkit-mask-image: radial-gradient(ellipse at 50% 47%, #000, transparent 75%); mask-image: radial-gradient(ellipse at 50% 47%, #000, transparent 75%); animation: gridpan 24s linear infinite; }
@keyframes gridpan { to { background-position: 72px 72px, 72px 72px; } }
.start-top { position: absolute; left: calc(28px + var(--safe-l)); right: calc(28px + var(--safe-r)); top: calc(24px + var(--safe-t)); display: flex; justify-content: space-between; }
.start-chip { display: flex; gap: 7px; align-items: center; font: 600 8px/1 var(--font-ui); letter-spacing: 0.2em; color: #81aab3; }
.start-chip i { width: 5px; height: 5px; background: var(--cyan); transform: rotate(45deg); box-shadow: 0 0 8px var(--cyan); }
.start-chip.right { color: #587e87; }
.start-content {
  position: absolute; left: 8.5%; top: 50%; transform: translateY(-50%); width: min(620px, 80vw);
  animation: startin 0.9s 0.1s cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes startin { from { opacity: 0; transform: translateY(calc(-50% + 24px)); } to { opacity: 1; transform: translateY(-50%); } }
.start-kicker { font: 600 10px/1.4 var(--font-ui); letter-spacing: 0.28em; color: #8db3ba; }
.start-kicker b { color: var(--cyan); font-weight: 600; }
.logo { position: relative; margin: 14px 0 0; font-family: var(--font-display); line-height: 0.78; letter-spacing: -0.015em; text-transform: uppercase; }
.logo-top, .logo-bottom { display: block; font-size: clamp(58px, 8.4vw, 122px); font-weight: 900; }
.logo-top { background: linear-gradient(180deg, #f8ffff 0%, #b7f6ff 38%, #3fc9dd 65%, #0e768b 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 2px 0 rgba(2, 16, 22, 0.85)) drop-shadow(0 0 28px rgba(98, 243, 255, 0.2)); }
.logo-bottom { margin-top: 0.05em; background: linear-gradient(180deg, #ffd6c9 0%, #ff6c51 40%, #cf2418 70%, #79110b 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 2px 0 rgba(2, 16, 22, 0.85)) drop-shadow(0 0 28px rgba(255, 70, 50, 0.16)); }
.logo em { display: inline-block; margin-top: 20px; padding: 7px 15px 6px; font: 700 13px/1 var(--font-display); font-style: normal; letter-spacing: 0.44em; color: #eafeff; background: rgba(4, 20, 27, 0.78); border-left: 2px solid var(--cyan); border-right: 1px solid rgba(98, 243, 255, 0.22); text-shadow: 0 0 16px rgba(98, 243, 255, 0.4); }
.tagline { max-width: 470px; margin: 18px 0 0; font: 400 12px/1.7 var(--font-ui); letter-spacing: 0.04em; color: #98b7bd; }
.start-actions { margin-top: 26px; }
.deploy {
  position: relative; pointer-events: auto; cursor: pointer; border: 1px solid rgba(98, 243, 255, 0.75);
  background: linear-gradient(110deg, rgba(12, 91, 106, 0.9), rgba(8, 34, 45, 0.9)); padding: 0; min-width: 300px;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  transition: filter 0.2s, transform 0.2s;
}
.deploy:hover { filter: brightness(1.3); transform: translateY(-1px); }
.deploy:active { transform: translateY(0); }
.deploy-inner { display: flex; justify-content: space-between; align-items: center; gap: 34px; padding: 17px 24px; font: 700 15px/1 var(--font-display); letter-spacing: 0.2em; color: #f2ffff; text-shadow: 0 0 14px rgba(98, 243, 255, 0.55); }
.deploy-inner b { font-size: 19px; color: var(--cyan); }
.deploy-load { position: absolute; left: 0; bottom: 0; height: 2px; width: 0; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); transition: width 0.4s; }
.deploy.ready .deploy-load { width: 100%; }
.deploy:disabled { cursor: wait; opacity: 0.7; }
.start-sub { margin-top: 9px; font: 500 7px/1 var(--font-ui); letter-spacing: 0.24em; color: #5c828b; }
.start-controls { display: flex; flex-wrap: wrap; gap: 12px 20px; max-width: 500px; margin-top: 28px; padding-top: 17px; border-top: 1px solid rgba(98, 243, 255, 0.14); }
.start-controls div { display: flex; align-items: center; gap: 6px; font: 500 8px/1 var(--font-ui); letter-spacing: 0.1em; color: #7da1a8; }
.start-controls kbd { height: 18px; font-size: 8px; }
.start-bottom { position: absolute; left: calc(28px + var(--safe-l)); right: calc(28px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); display: flex; justify-content: space-between; align-items: center; font: 500 7px/1 var(--font-ui); letter-spacing: 0.2em; color: #51717a; }
.start-status { display: flex; gap: 7px; align-items: center; color: #8bbac3; }
.start-status i { width: 5px; height: 5px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 7px var(--gold); animation: pulse 1.4s infinite; }
.corner { position: absolute; width: 38px; height: 38px; border-color: rgba(98, 243, 255, 0.5); border-style: solid; pointer-events: none; }
.corner.tl { left: 18px; top: 18px; border-width: 1px 0 0 1px; }
.corner.tr { right: 18px; top: 18px; border-width: 1px 1px 0 0; }
.corner.bl { left: 18px; bottom: 18px; border-width: 0 0 1px 1px; }
.corner.br { right: 18px; bottom: 18px; border-width: 0 1px 1px 0; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }

/* ------------------------------------------------------------------ overlays */
.overlay { position: absolute; inset: 0; z-index: 50; display: grid; place-items: center; background: rgba(1, 7, 10, 0.7); backdrop-filter: blur(8px); }
.overlay-card { position: relative; width: min(560px, calc(100vw - 32px)); padding: 34px 38px 30px; text-align: left; }
.overlay-kicker { font: 600 8px/1 var(--font-ui); letter-spacing: 0.3em; color: var(--cyan); }
.overlay-card h2 { margin: 9px 0 0; font: 900 clamp(38px, 7vw, 64px)/0.9 var(--font-display); letter-spacing: 0.04em; color: #f3feff; text-shadow: 0 0 30px rgba(98, 243, 255, 0.3); }
.overlay-card p { margin: 13px 0 0; font: 400 12px/1.65 var(--font-ui); color: #94b2b9; }
.pause-actions { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 22px; }
.btn { pointer-events: auto; cursor: pointer; padding: 12px 18px; border: 1px solid rgba(98, 243, 255, 0.26); background: rgba(6, 25, 33, 0.8); font: 600 10px/1 var(--font-display); letter-spacing: 0.16em; color: #b6dde4; transition: 0.18s; }
.btn:hover { border-color: var(--cyan); color: #fff; background: rgba(12, 52, 65, 0.9); }
.btn.primary { border-color: rgba(98, 243, 255, 0.7); background: linear-gradient(110deg, rgba(17, 105, 120, 0.9), rgba(8, 39, 50, 0.9)); color: #fff; }
.btn.primary b { color: var(--cyan); }
.btn.danger:hover { border-color: #ff5648; color: #ffc7c0; }
.pause-controls { display: flex; flex-wrap: wrap; gap: 10px 16px; margin-top: 24px; padding-top: 17px; border-top: 1px solid rgba(98, 243, 255, 0.14); }
.pause-controls span { display: flex; gap: 5px; align-items: center; font: 500 8px/1 var(--font-ui); letter-spacing: 0.09em; color: #72959d; }
.overlay-card.danger-card h2 { color: #ffd8d3; text-shadow: 0 0 30px rgba(255, 60, 40, 0.45); }
.overlay-card.danger-card .overlay-kicker { color: #ff6d5b; }
.stat-row { display: flex; justify-content: space-between; margin-top: 20px; padding-top: 14px; border-top: 1px solid rgba(255, 100, 80, 0.2); font: 600 9px/1 var(--font-ui); letter-spacing: 0.16em; color: #a98380; }
.stat-row b { color: #ffe9e5; }
.victory-card .overlay-kicker { color: var(--gold); }
.victory-card h2 { color: #fff8e1; text-shadow: 0 0 34px rgba(255, 200, 90, 0.4); }
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; margin-top: 20px; background: rgba(98, 243, 255, 0.13); }
.stat-grid > div { background: rgba(5, 20, 27, 0.92); padding: 12px 14px; }
.stat-grid span { display: block; font: 600 7px/1 var(--font-ui); letter-spacing: 0.2em; color: #6e99a2; }
.stat-grid b { display: block; margin-top: 5px; font: 700 22px/1 var(--font-display); letter-spacing: 0.06em; color: var(--gold); }

#loading { position: absolute; inset: 0; z-index: 60; display: grid; place-items: center; background: #041015; }
.loading-inner { display: flex; flex-direction: column; align-items: center; gap: 14px; font: 600 9px/1 var(--font-ui); letter-spacing: 0.34em; color: #7fbcc6; }
.loading-inner i { width: 42px; height: 42px; border: 1px solid rgba(98, 243, 255, 0.2); border-top-color: var(--cyan); border-radius: 50%; animation: spin 0.9s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

@keyframes hud-in { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }

/* ------------------------------------------------------------------ responsive */
@media (max-width: 1080px) {
  #player-panel { width: 288px; }
  #map-panel { width: 200px; }
  #objective-panel { top: calc(286px + var(--safe-t)); width: 250px; }
  #hint-bar { display: none; }
  #feed { display: none; }
  .start-content { left: 6%; }
}
@media (max-width: 760px), (pointer: coarse) {
  #game { cursor: default; }
  #player-panel { left: calc(10px + var(--safe-l)); top: calc(8px + var(--safe-t)); width: 232px; padding: 10px 11px 9px; }
  .avatar { width: 30px; height: 30px; }
  .avatar svg { width: 21px; height: 21px; }
  .id-name { font-size: 12px; }
  .id-name span { display: none; }
  .id-status { font-size: 6.5px; }
  .score span { display: none; }
  .score b { font-size: 13px; }
  .bar-row { margin-top: 6px; }
  .bar-label { font-size: 6.5px; margin-bottom: 3px; }
  .bar { height: 6px; }
  .ability-row { display: none; }
  #map-panel { right: calc(10px + var(--safe-r)); top: calc(8px + var(--safe-t)); width: 126px; padding: 6px; }
  .map-head { font-size: 6px; letter-spacing: 0.1em; margin-bottom: 4px; }
  .map-head b { font-size: 7px; }
  .map-foot { font-size: 6px; margin-top: 4px; letter-spacing: 0.06em; }
  .map-foot b { font-size: 11px; }
  .map-coords { font-size: 5.5px; left: 4px; bottom: 3px; }
  #objective-panel { display: none; }
  #weapon-panel { left: calc(50% + 8px); transform: translateX(-50%); bottom: calc(6px + var(--safe-b)); width: 164px; height: 54px; padding: 7px 12px; gap: 8px; background: rgba(5, 18, 26, 0.55); }
  .weapon-icon { width: 28px; padding-right: 7px; }
  .weapon-icon svg { width: 26px; height: 15px; }
  .weapon-name { font-size: 9px; }
  .weapon-desc { font-size: 5.5px; letter-spacing: 0.08em; }
  .heat { height: 3px; margin-top: 5px; }
  .heat span { display: none; }
  .weapon-slots { display: none; }
  #hint-bar, #feed, #compass { display: none; }
  #mode-tag { bottom: calc(145px + var(--safe-b)); font-size: 7px; }
  #banner { top: 19%; min-width: 0; width: calc(100vw - 40px); padding: 13px 20px; }
