import * as THREE from 'three';
import { clamp, dist2D, makeGlowTexture, makeSprite } from './utils.js';
import { WATER_LEVEL } from './world.js';

const HEALTH_SPOTS = [
  [-30, 250], [90, 90], [-170, 210], [-268, -30], [250, -20],
  [140, -220], [-250, -190], [-90, -380], [220, -330], [330, 60],
  [-430, -160], [40, -90], [430, -240], [-80, 360]
];

const ENERGY_SPOTS = [
  [34, 200], [-110, 60], [-220, 120], [180, -70], [300, -250],
  [-300, -260], [-60, -300], [120, -410], [420, -120], [-460, -300],
  [-130, -120], [250, 210]
];

export class PickupManager {
  constructor(scene, world, effects, audio) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.glowTexture = makeGlowTexture(128);
    this.relics = [];
    this.canisters = [];
    this.shards = [];
    this.onRelic = null;
    this.onHeal = null;
    this.onEnergy = null;
    this.onShard = null;
    this.time = 0;
    this.buildRelics();
    this.buildCanisters();
  }

  buildRelics() {
    for (const site of this.world.relics) {
      const group = new THREE.Group();
      const y = site.y + 3.35;
      group.position.set(site.x, y, site.z);
      const color = new THREE.Color(site.color);

      const coreMat = new THREE.MeshStandardMaterial({
        color: new THREE.Color(site.color).multiplyScalar(0.25),
        emissive: site.color, emissiveIntensity: 2.2,
        metalness: 0.65, roughness: 0.15
      });
      const core = new THREE.Mesh(new THREE.OctahedronGeometry(0.72, 0), coreMat);
      core.castShadow = true;
      group.add(core);

      const inner = new THREE.Mesh(
        new THREE.IcosahedronGeometry(1.0, 0),
        new THREE.MeshBasicMaterial({ color: site.color, wireframe: true, transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
      );
      group.add(inner);

      const ringMat = new THREE.MeshStandardMaterial({
        color: 0x141c22, emissive: site.color, emissiveIntensity: 1.1,
        metalness: 0.8, roughness: 0.3
      });
      const ring1 = new THREE.Mesh(new THREE.TorusGeometry(1.22, 0.035, 4, 40), ringMat);
      ring1.rotation.x = Math.PI / 2.4;
      group.add(ring1);
      const ring2 = new THREE.Mesh(new THREE.TorusGeometry(1.42, 0.025, 4, 40), ringMat);
      ring2.rotation.y = Math.PI / 2.2;
      group.add(ring2);

      const glow = makeSprite(this.glowTexture, site.color, 5.2);
      glow.material.opacity = 0.5;
      group.add(glow);

      // Orbiting fragments
      const shards = [];
      for (let i = 0; i < 5; i++) {
        const shard = new THREE.Mesh(new THREE.TetrahedronGeometry(0.12, 0), coreMat);
        shard.userData.angle = (i / 5) * Math.PI * 2;
        shard.userData.radius = 1.6 + Math.random() * 0.3;
        shard.userData.height = (Math.random() - 0.5) * 1.1;
        group.add(shard);
        shards.push(shard);
      }

      this.scene.add(group);
      this.relics.push({
        site,
        group,
        core,
        inner,
        ring1,
        ring2,
        glow,
        shards,
        baseY: y,
        collected: false
      });
      site.pickup = group;
    }
  }

  buildCanisters() {
    const crossMat = new THREE.MeshStandardMaterial({
      color: 0x0c2a18, emissive: 0x74f7a8, emissiveIntensity: 1.8, metalness: 0.5, roughness: 0.25
    });
    const cellMat = new THREE.MeshStandardMaterial({
      color: 0x0a2e3a, emissive: 0x62f3ff, emissiveIntensity: 1.8, metalness: 0.5, roughness: 0.25
    });
    for (const [x, z] of HEALTH_SPOTS) {
      const y = this.world.heightAt(x, z);
      if (y < WATER_LEVEL + 0.3) continue;
      const group = new THREE.Group();
      group.position.set(x, y + 1.2, z);
      const box1 = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.22, 0.22), crossMat);
      const box2 = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.7, 0.22), crossMat);
      group.add(box1, box2);
      const cage = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.95, 0.95), new THREE.MeshBasicMaterial({
        color: 0x74f7a8, wireframe: true, transparent: true, opacity: 0.22, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      group.add(cage);
      const glow = makeSprite(this.glowTexture, 0x74f7a8, 2.6);
      glow.material.opacity = 0.4;
      group.add(glow);
      const beam = new THREE.Mesh(
        new THREE.CylinderGeometry(0.08, 0.5, 8, 8, 1, true),
        new THREE.MeshBasicMaterial({ color: 0x74f7a8, transparent: true, opacity: 0.08, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
      );
      beam.position.y = 4;
      group.add(beam);
      this.scene.add(group);
      this.canisters.push({ type: 'health', group, x, z, y: y + 1.2, baseY: y + 1.2, active: true, timer: 0, spin: cage });
    }
    for (const [x, z] of ENERGY_SPOTS) {
      const y = this.world.heightAt(x, z);
      if (y < WATER_LEVEL + 0.3) continue;
      const group = new THREE.Group();
      group.position.set(x, y + 1.2, z);
      const cell = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.3, 0.85, 6), cellMat);
      group.add(cell);
      for (let i = 0; i < 3; i++) {
        const band = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.035, 4, 12), new THREE.MeshBasicMaterial({
          color: 0x9ffaff, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false
        }));
        band.rotation.x = Math.PI / 2;
        band.position.y = -0.28 + i * 0.28;
        group.add(band);
      }
      const glow = makeSprite(this.glowTexture, 0x62f3ff, 2.4);
      glow.material.opacity = 0.4;
      group.add(glow);
      const beam = new THREE.Mesh(
        new THREE.CylinderGeometry(0.08, 0.45, 7, 8, 1, true),
        new THREE.MeshBasicMaterial({ color: 0x62f3ff, transparent: true, opacity: 0.07, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
      );
      beam.position.y = 3.5;
      group.add(beam);
      this.scene.add(group);
      this.canisters.push({ type: 'energy', group, x, z, y: y + 1.2, baseY: y + 1.2, active: true, timer: 0, spin: null });
    }
  }

  spawnShard(pos, value = 30, energon = 5) {
    const group = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({ color: 0x143d44, emissive: 0x62f3ff, emissiveIntensity: 2.2, metalness: 0.4, roughness: 0.2 });
    const mesh = new THREE.Mesh(new THREE.OctahedronGeometry(0.28, 0), mat);
    group.add(mesh);
    const glow = makeSprite(this.glowTexture, 0x62f3ff, 1.1);
    group.add(glow);
    this.scene.add(group);
    const start = pos.clone();
    group.position.copy(start);
    this.shards.push({
      group, mesh, glow, value, energon,
      vel: new THREE.Vector3((Math.random() - 0.5) * 4, 4 + Math.random() * 3, (Math.random() - 0.5) * 4),
      life: 32, age: 0, grounded: false, collected: false
    });
  }

  collectRelic(entry) {
    entry.collected = true;
    entry.site.collected = true;
    entry.group.visible = false;
    if (entry.site.beam) entry.site.beam.visible = false;
    if (entry.site.marker) entry.site.marker.visible = false;
    const pos = entry.group.position.clone();
    this.effects.pickupBurst(pos, entry.site.color);
    this.audio?.relicPickup();
    if (this.onRelic) this.onRelic(entry.site);
  }

  update(dt, player, elapsed) {
    this.time += dt;
    for (const r of this.relics) {
      if (r.collected) continue;
      const t = elapsed;
      r.group.position.y = r.baseY + Math.sin(t * 1.3 + r.site.x * 0.03) * 0.28;
      r.core.rotation.y += dt * 0.8;
      r.core.rotation.x += dt * 0.35;
      r.inner.rotation.y -= dt * 0.45;
      r.inner.rotation.z += dt * 0.2;
      r.ring1.rotation.z += dt * 0.6;
      r.ring2.rotation.x += dt * 0.4;
      r.glow.material.opacity = 0.42 + Math.sin(t * 2.2) * 0.12;
      for (const shard of r.shards) {
        const a = shard.userData.angle + t * 0.8;
        shard.position.set(
          Math.cos(a) * shard.userData.radius,
          shard.userData.height + Math.sin(t * 1.8 + a) * 0.25,
          Math.sin(a) * shard.userData.radius
        );
        shard.rotation.x += dt * 2;
        shard.rotation.y += dt * 1.4;
      }
      if (player && !player.dead) {
        const d = dist2D(player.position.x, player.position.z, r.site.x, r.site.z);
        if (d < 3.2 && Math.abs(player.position.y + 1.8 - r.group.position.y) < 5.5) {
          this.collectRelic(r);
        }
      }
    }

    for (const c of this.canisters) {
      if (!c.active) {
        c.timer -= dt;
        if (c.timer <= 0) {
          c.active = true;
          c.group.visible = true;
          c.group.scale.setScalar(0.2);
        }
        continue;
      }
      c.group.position.y = c.baseY + Math.sin(elapsed * 1.6 + c.x * 0.1) * 0.12;
      c.group.rotation.y += dt * (c.type === 'health' ? 0.9 : 1.4);
      if (c.spin) c.spin.rotation.x += dt * 0.6;
      const targetScale = 1;
      if (c.group.scale.x < targetScale) c.group.scale.setScalar(Math.min(targetScale, c.group.scale.x + dt * 1.8));
      if (player && !player.dead) {
        const d = dist2D(player.position.x, player.position.z, c.x, c.z);
        if (d < 2.2 && Math.abs(player.position.y + 1.5 - c.group.position.y) < 4) {
          c.active = false;
          c.group.visible = false;
          c.timer = c.type === 'health' ? 32 : 24;
          if (c.type === 'health') {
            player.health = Math.min(player.maxHealth, player.health + 35);
            this.effects.healBurst(player.position.clone().add(new THREE.Vector3(0, 2, 0)));
            this.audio?.healthPickup();
            if (this.onHeal) this.onHeal(35);
          } else {
            player.energon = Math.min(player.maxEnergon, player.energon + 45);
            player.addScore(120);
            this.effects.pickupBurst(player.position.clone().add(new THREE.Vector3(0, 2, 0)), 0x62f3ff);
            this.audio?.energyPickup();
            if (this.onEnergy) this.onEnergy(45);
          }
        }
      }
    }

    for (let i = this.shards.length - 1; i >= 0; i--) {
      const s = this.shards[i];
      s.age += dt;
      s.life -= dt;
      if (s.life <= 0) {
        s.group.visible = false;
        this.scene.remove(s.group);
        this.shards.splice(i, 1);
        continue;
      }
      s.mesh.rotation.y += dt * 4;
      s.mesh.rotation.x += dt * 2;
      const ground = this.world.heightAt(s.group.position.x, s.group.position.z);
      if (!s.grounded) {
        s.vel.y -= 20 * dt;
        s.group.position.addScaledVector(s.vel, dt);
        if (s.group.position.y <= ground + 0.3) {
          s.group.position.y = ground + 0.3;
          s.vel.y = Math.abs(s.vel.y) * 0.4;
          s.vel.x *= 0.5;
          s.vel.z *= 0.5;
          if (s.vel.y < 0.6) {
            s.vel.set(0, 0, 0);
            s.grounded = true;
          }
        }
      }
      if (player && !player.dead && s.age > 0.45) {
        const toPlayer = new THREE.Vector3(
          player.position.x - s.group.position.x,
          player.position.y + 1.8 - s.group.position.y,
          player.position.z - s.group.position.z
        );
        const dist = toPlayer.length();
        if (dist < 15) {
          toPlayer.normalize();
          const pull = (1 - dist / 15) * 28 + 8;
          s.group.position.addScaledVector(toPlayer, pull * dt);
          s.grounded = true;
          if (dist < 1.35) {
            player.addScore(s.value);
            player.energon = Math.min(player.maxEnergon, player.energon + s.energon);
            this.effects.sparks(s.group.position.clone(), 5, 0x62f3ff, 0.7, { life: 0.3 });
            this.audio?.shard();
            if (this.onShard) this.onShard(s.value);
            this.scene.remove(s.group);
            this.shards.splice(i, 1);
          }
        }
      }
      s.glow.material.opacity = 0.4 + Math.sin(s.age * 6) * 0.15;
    }
  }
}

import { clamp } from './utils.js';

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.mouseDX = 0;
    this.mouseDY = 0;
    this.fire = false;
    this.ability = false;
    this.mouseLocked = false;
    this.enabled = false;
    this.sensitivity = 0.0022;
    this.touchSensitivity = 0.005;
    this.joystick = { x: 0, y: 0, active: false, pointerId: null };
    this.touchFire = false;
    this.touchAbility = false;
    this.jumpPressed = false;
    this.weaponCycle = false;
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.dragging = false;
    this.dragPointer = null;
    this.lastDragX = 0;
    this.lastDragY = 0;
    this.onPauseRequest = null;
    this.onLockChange = null;
    this.wasLocked = false;

    this.bindKeyboard();
    this.bindMouse();
    this.bindTouch();
  }

  get moveX() {
    let value = 0;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) value += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) value -= 1;
    value += this.joystick.x;
    return clamp(value, -1, 1);
  }

  get moveZ() {
    let value = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) value += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) value -= 1;
    value += -this.joystick.y;
    const x = this.moveX;
    const len = Math.hypot(x, value);
    if (len > 1) {
      value /= len;
    }
    return clamp(value, -1, 1);
  }

  get sprint() {
    return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
  }

  bindKeyboard() {
    window.addEventListener('keydown', (event) => {
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(event.code)) event.preventDefault();
      if (event.code === 'Escape') {
        if (this.onPauseRequest) this.onPauseRequest();
        return;
      }
      if (!this.enabled) return;
      if (event.repeat) return;
      this.keys.add(event.code);
      this.pressed.add(event.code);
      if (event.code === 'Space') this.jumpPressed = true;
      if (event.code === 'KeyM') {
        // handled by the game through pressed set
      }
    });
    window.addEventListener('keyup', (event) => {
      this.keys.delete(event.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.fire = false;
      this.ability = false;
    });
  }

  bindMouse() {
    this.canvas.addEventListener('mousedown', (event) => {
      if (!this.enabled) return;
      if (event.button === 0) {
        this.fire = true;
        if (!this.isTouch && !this.mouseLocked) this.requestPointerLock();
      }
    });
    window.addEventListener('mouseup', (event) => {
      if (event.button === 0) this.fire = false;
    });
    window.addEventListener('mousemove', (event) => {
      if (!this.enabled) return;
      if (this.mouseLocked) {
        this.mouseDX += event.movementX || 0;
        this.mouseDY += event.movementY || 0;
      } else if (this.dragging && event.pointerType !== 'touch') {
        this.mouseDX += event.clientX - this.lastDragX;
        this.mouseDY += event.clientY - this.lastDragY;
        this.lastDragX = event.clientX;
        this.lastDragY = event.clientY;
      }
    });
    this.canvas.addEventListener('mousedown', (event) => {
      if (!this.enabled || event.button !== 0 || this.mouseLocked || this.isTouch) return;
      this.dragging = true;
      this.lastDragX = event.clientX;
      this.lastDragY = event.clientY;
    });
    window.addEventListener('mouseup', () => { this.dragging = false; });
    this.canvas.addEventListener('contextmenu', (event) => event.preventDefault());
    window.addEventListener('wheel', (event) => {
      if (!this.enabled) return;
      this.weaponCycle = true;
    }, { passive: true });
    document.addEventListener('pointerlockchange', () => {
      this.mouseLocked = document.pointerLockElement === this.canvas;
      this.canvas.classList.toggle('locked', this.mouseLocked);
      if (this.onLockChange) this.onLockChange(this.mouseLocked, this.wasLocked);
      this.wasLocked = this.mouseLocked;
    });
  }

  requestPointerLock() {
    if (this.isTouch) return;
    this.canvas.requestPointerLock?.();
  }

  exitPointerLock() {
    if (document.pointerLockElement) document.exitPointerLock?.();
  }

  bindTouch() {
    const joy = document.getElementById('joystick');
    const stick = document.getElementById('joystick-stick');
    if (joy) {
      const radius = 46;
      const updateStick = (dx, dy) => {
        const len = Math.hypot(dx, dy);
        const clamped = len > radius ? radius / len : 1;
        const x = dx * clamped;
        const y = dy * clamped;
        stick.style.transform = `translate(${x}px, ${y}px)`;
        this.joystick.x = x / radius;
        this.joystick.y = y / radius;
      };
      joy.addEventListener('pointerdown', (event) => {
        if (!this.enabled) return;
        event.preventDefault();
        event.stopPropagation();
        this.joystick.active = true;
        this.joystick.pointerId = event.pointerId;
        joy.setPointerCapture(event.pointerId);
        const rect = joy.getBoundingClientRect();
        updateStick(event.clientX - (rect.left + rect.width / 2), event.clientY - (rect.top + rect.height / 2));
      });
      joy.addEventListener('pointermove', (event) => {
        if (!this.joystick.active || event.pointerId !== this.joystick.pointerId) return;
        event.preventDefault();
        const rect = joy.getBoundingClientRect();
        updateStick(event.clientX - (rect.left + rect.width / 2), event.clientY - (rect.top + rect.height / 2));
      });
      const end = (event) => {
        if (event.pointerId !== this.joystick.pointerId) return;
        this.joystick.active = false;
        this.joystick.pointerId = null;
        this.joystick.x = 0;
        this.joystick.y = 0;
        stick.style.transform = 'translate(0px, 0px)';
      };
      joy.addEventListener('pointerup', end);
      joy.addEventListener('pointercancel', end);
      joy.addEventListener('lostpointercapture', end);
    }

    const hold = (id, onDown, onUp) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('pointerdown', (event) => {
        if (!this.enabled) return;
        event.preventDefault();
        event.stopPropagation();
        el.classList.add('down');
        el.setPointerCapture(event.pointerId);
        onDown();
      });
      const up = (event) => {
        event.preventDefault();
        event.stopPropagation();
        el.classList.remove('down');
        onUp?.();
      };
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      el.addEventListener('lostpointercapture', () => el.classList.remove('down'));
    };
    hold('btn-fire', () => { this.touchFire = true; }, () => { this.touchFire = false; });
    hold('btn-ability', () => { this.touchAbility = true; }, () => { this.touchAbility = false; });
    hold('btn-jump', () => { this.jumpPressed = true; });
    hold('btn-transform', () => { this.pressed.add('KeyF'); });
    hold('btn-weapon', () => { this.weaponCycle = true; });

    // Camera look drag on the canvas (right side / anywhere not on controls).
    this.canvas.addEventListener('pointerdown', (event) => {
      if (!this.enabled || !this.isTouch || event.pointerType !== 'touch') return;
      this.dragging = true;
      this.dragPointer = event.pointerId;
      this.lastDragX = event.clientX;
      this.lastDragY = event.clientY;
    });
    this.canvas.addEventListener('pointermove', (event) => {
      if (!this.enabled || !this.dragging || event.pointerId !== this.dragPointer) return;
      const dx = event.clientX - this.lastDragX;
      const dy = event.clientY - this.lastDragY;
      this.lastDragX = event.clientX;
      this.lastDragY = event.clientY;
      this.mouseDX += dx;
      this.mouseDY += dy;
    });
    const endDrag = (event) => {
      if (event.pointerId === this.dragPointer) {
        this.dragging = false;
        this.dragPointer = null;
      }
    };
    this.canvas.addEventListener('pointerup', endDrag);
    this.canvas.addEventListener('pointercancel', endDrag);
  }

  get abilityHeld() {
    return this.keys.has('KeyQ') || this.touchAbility;
  }

  get fireHeld() {
    return this.fire || this.touchFire;
  }

  update() {
    this.ability = this.abilityHeld;
    this.fire = this.fireHeld;
    this.jumpPressed = this.jumpPressed || this.pressed.has('Space');
  }

  endFrame() {
    this.pressed.clear();
    this.jumpPressed = false;
    this.weaponCycle = false;
    this.mouseDX = 0;
    this.mouseDY = 0;
  }

  clear() {
    this.keys.clear();
    this.pressed.clear();
    this.fire = false;
    this.touchFire = false;
    this.touchAbility = false;
    this.ability = false;
    this.joystick.x = 0;
    this.joystick.y = 0;
    this.mouseDX = 0;
    this.mouseDY = 0;
  }

  showTouchUI(show) {
    const ui = document.getElementById('touch-ui');
    if (!ui) return;
    const shouldShow = show && this.isTouch;
    ui.classList.toggle('hidden', !shouldShow);
    document.body.classList.toggle('touch', shouldShow);
  }
}

import { clamp } from './utils.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.ready = false;
    this.engineOn = false;
    this.boost = false;
    this.waterOn = false;
    this.bossLayer = false;
  }

  unlock() {
    if (this.ready) {
      this.ctx?.resume?.();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    this.ctx = ctx;
    const compressor = ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 22;
    compressor.ratio.value = 8;
    compressor.attack.value = 0.004;
    compressor.release.value = 0.22;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(compressor);
    compressor.connect(ctx.destination);

    this.music = ctx.createGain();
    this.music.gain.value = 0.5;
    this.music.connect(this.master);
    this.sfx = ctx.createGain();
    this.sfx.gain.value = 0.72;
    this.sfx.connect(this.master);

    this.noiseBuffer = this.makeNoise(ctx, 2.2);
    this.ready = true;
    this.startAmbient();
    this.createEngine();
    this.createWater();
    this.createBossLayer();
  }

  makeNoise(ctx, seconds) {
    const length = Math.floor(ctx.sampleRate * seconds);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    return buffer;
  }

  startAmbient() {
    const ctx = this.ctx;
    const noise = ctx.createBufferSource();
    noise.buffer = this.noiseBuffer;
    noise.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    filter.Q.value = 0.4;
    const gain = ctx.createGain();
    gain.gain.value = 0.11;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.music);
    noise.start();
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.06;
    lfoGain.gain.value = 130;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();

    // Low, slow forest drone.
    const droneGain = ctx.createGain();
    droneGain.gain.value = 0.038;
    droneGain.connect(this.music);
    for (const [freq, type, detune] of [[55, 'sine', 0], [82.5, 'triangle', 5], [110, 'sine', -7]]) {
      const osc = ctx.createOscillator();
      osc.type = type;
      osc.frequency.value = freq;
      osc.detune.value = detune;
      const g = ctx.createGain();
      g.gain.value = 0.4;
      osc.connect(g);
      g.connect(droneGain);
      osc.start();
    }
    const droneLfo = ctx.createOscillator();
    const droneLfoGain = ctx.createGain();
    droneLfo.frequency.value = 0.033;
    droneLfoGain.gain.value = 0.018;
    droneLfo.connect(droneLfoGain);
    droneLfoGain.connect(droneGain.gain);
    droneLfo.start();

    // Sparse distant bird-like pings.
    this.ambientTimer = 0;
  }

  createEngine() {
    const ctx = this.ctx;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineGain.connect(this.sfx);
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 360;
    this.engineFilter.Q.value = 2.2;
    this.engineFilter.connect(this.engineGain);
    this.engineOscA = ctx.createOscillator();
    this.engineOscA.type = 'sawtooth';
    this.engineOscA.frequency.value = 44;
    this.engineOscA.connect(this.engineFilter);
    this.engineOscB = ctx.createOscillator();
    this.engineOscB.type = 'square';
    this.engineOscB.frequency.value = 67;
    const bGain = ctx.createGain();
    bGain.gain.value = 0.25;
    this.engineOscB.connect(bGain);
    bGain.connect(this.engineFilter);
    this.engineOscA.start();
    this.engineOscB.start();
  }

  createWater() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 780;
    filter.Q.value = 0.7;
    this.waterGain = ctx.createGain();
    this.waterGain.gain.value = 0;
    src.connect(filter);
    filter.connect(this.waterGain);
    this.waterGain.connect(this.sfx);
    src.start();
  }

  createBossLayer() {
    const ctx = this.ctx;
    this.bossGain = ctx.createGain();
    this.bossGain.gain.value = 0;
    this.bossGain.connect(this.music);
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = 36.7;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 160;
    filter.Q.value = 4;
    osc.connect(filter);
    filter.connect(this.bossGain);
    osc.start();
    const pulse = ctx.createOscillator();
    const pulseGain = ctx.createGain();
    pulse.frequency.value = 2.6;
    pulseGain.gain.value = 0.5;
    pulse.connect(pulseGain);
    pulseGain.connect(this.bossGain.gain);
    pulse.start();
    this.bossGain.gain.value = 0;
  }

  setEngine(on) {
    if (!this.ready) return;
    this.engineOn = on;
    const now = this.ctx.currentTime;
    this.engineGain.gain.cancelScheduledValues(now);
    this.engineGain.gain.setTargetAtTime(on ? 0.085 : 0, now, 0.12);
  }

  setBoost(on) {
    this.boost = on;
  }

  setWater(on) {
    if (!this.ready || on === this.waterOn) return;
    this.waterOn = on;
    this.waterGain.gain.setTargetAtTime(on ? 0.05 : 0, this.ctx.currentTime, 0.2);
  }

  updateEngine(speedRatio) {
    if (!this.ready || !this.engineOn) return;
    const now = this.ctx.currentTime;
    const ratio = clamp(speedRatio, 0, 1.4);
    this.engineOscA.frequency.setTargetAtTime(42 + ratio * 58 + (this.boost ? 22 : 0), now, 0.08);
    this.engineOscB.frequency.setTargetAtTime(63 + ratio * 90, now, 0.08);
    this.engineFilter.frequency.setTargetAtTime(260 + ratio * 950 + (this.boost ? 420 : 0), now, 0.1);
    this.engineGain.gain.setTargetAtTime(this.engineOn ? 0.055 + ratio * 0.035 + (this.boost ? 0.03 : 0) : 0, now, 0.1);
  }

  setBossMode(on) {
    if (!this.ready) return;
    this.bossLayer = on;
    this.bossGain.gain.setTargetAtTime(on ? 0.055 : 0, this.ctx.currentTime, 0.8);
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  tone({ freq = 440, endFreq = null, type = 'sine', dur = 0.2, gain = 0.15, attack = 0.006, delay = 0, dest = null, filter = null, q = 1 }) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(1, freq), t0);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(1, endFreq), t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(gain, t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    let node = osc;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = filter;
      f.frequency.value = Math.max(60, freq * 2.4);
      f.Q.value = q;
      node.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(dest || this.sfx);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  noise({ dur = 0.2, gain = 0.12, freq = 800, type = 'lowpass', q = 1, delay = 0, dest = null, slideTo = null }) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(Math.max(40, freq), t0);
    filter.Q.value = q;
    if (slideTo) filter.frequency.exponentialRampToValueAtTime(Math.max(40, slideTo), t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(gain, t0 + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(dest || this.sfx);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  shoot(type) {
    if (type === 'mortar') {
      this.tone({ freq: 180, endFreq: 48, type: 'sawtooth', dur: 0.28, gain: 0.2, filter: 'lowpass' });
      this.noise({ dur: 0.22, gain: 0.16, freq: 1200, slideTo: 180 });
    } else if (type === 'repeater') {
      this.tone({ freq: 1350 + Math.random() * 120, endFreq: 420, type: 'square', dur: 0.07, gain: 0.055 });
      this.tone({ freq: 620, endFreq: 210, type: 'sawtooth', dur: 0.08, gain: 0.05 });
    } else {
      this.tone({ freq: 940, endFreq: 240, type: 'square', dur: 0.13, gain: 0.08 });
      this.tone({ freq: 320, endFreq: 90, type: 'sawtooth', dur: 0.16, gain: 0.06 });
    }
  }

  hit() {
    this.tone({ freq: 720, endFreq: 380, type: 'triangle', dur: 0.06, gain: 0.07 });
    this.noise({ dur: 0.06, gain: 0.05, freq: 1800, type: 'hipass' });
  }

  enemyShoot() {
    this.tone({ freq: 420, endFreq: 120, type: 'sawtooth', dur: 0.16, gain: 0.06 });
  }

  enemyHit(big) {
    this.noise({ dur: 0.12, gain: big ? 0.14 : 0.08, freq: big ? 600 : 1100, type: 'bandpass', q: 0.8 });
    this.tone({ freq: big ? 140 : 260, endFreq: 60, type: 'square', dur: 0.12, gain: 0.05 });
  }

  enemyDeath(big) {
    this.noise({ dur: big ? 0.7 : 0.45, gain: big ? 0.25 : 0.16, freq: big ? 500 : 900, slideTo: 90 });
    this.tone({ freq: big ? 90 : 150, endFreq: 30, type: 'sawtooth', dur: 0.5, gain: 0.12 });
  }

  explosion(scale = 1) {
    this.noise({ dur: 0.55 * scale, gain: 0.22 * scale, freq: 700 * scale, slideTo: 60 });
    this.tone({ freq: 110 * scale, endFreq: 24, type: 'sine', dur: 0.55 * scale, gain: 0.18 * scale });
  }

  slam() {
    this.tone({ freq: 90, endFreq: 28, type: 'sine', dur: 0.4, gain: 0.24 });
    this.noise({ dur: 0.35, gain: 0.18, freq: 300, slideTo: 50 });
  }

  playerHit() {
    this.tone({ freq: 220, endFreq: 70, type: 'sawtooth', dur: 0.26, gain: 0.14 });
    this.noise({ dur: 0.2, gain: 0.14, freq: 900, type: 'bandpass', q: 0.7 });
  }

  shieldHit() {
    this.tone({ freq: 880, endFreq: 1320, type: 'sine', dur: 0.18, gain: 0.07 });
    this.tone({ freq: 1320, endFreq: 660, type: 'triangle', dur: 0.24, gain: 0.05 });
  }

  jump() {
    this.tone({ freq: 220, endFreq: 520, type: 'triangle', dur: 0.16, gain: 0.08 });
    this.noise({ dur: 0.18, gain: 0.06, freq: 900, type: 'bandpass' });
  }

  jets() {
    this.noise({ dur: 0.5, gain: 0.14, freq: 1600, type: 'bandpass', q: 1.4 });
    this.tone({ freq: 160, endFreq: 620, type: 'sawtooth', dur: 0.3, gain: 0.06 });
  }

  land(impact) {
    this.noise({ dur: 0.22, gain: 0.08 + impact * 0.12, freq: 320, slideTo: 80 });
    this.tone({ freq: 90, endFreq: 45, type: 'sine', dur: 0.2, gain: 0.08 + impact * 0.08 });
  }

  transform(toVehicle) {
    this.noise({ dur: 0.42, gain: 0.1, freq: toVehicle ? 1600 : 700, slideTo: toVehicle ? 420 : 1900, type: 'bandpass', q: 1.8 });
    this.tone({ freq: toVehicle ? 190 : 380, endFreq: toVehicle ? 380 : 190, type: 'sawtooth', dur: 0.4, gain: 0.05, filter: 'lowpass' });
    for (let i = 0; i < 3; i++) {
      this.tone({ freq: 420 + i * 130, endFreq: 320, type: 'square', dur: 0.09, gain: 0.04, delay: i * 0.1 });
    }
  }

  transformClank() {
    this.noise({ dur: 0.12, gain: 0.18, freq: 700, type: 'bandpass', q: 1.4 });
    this.tone({ freq: 180, endFreq: 80, type: 'square', dur: 0.14, gain: 0.1 });
    this.tone({ freq: 640, endFreq: 420, type: 'triangle', dur: 0.2, gain: 0.05 });
  }

  weaponSwitch() {
    this.tone({ freq: 540, endFreq: 760, type: 'square', dur: 0.06, gain: 0.04 });
  }

  weaponReady() {
    this.tone({ freq: 660, endFreq: 990, type: 'triangle', dur: 0.12, gain: 0.06 });
  }

  overheat() {
    this.noise({ dur: 0.5, gain: 0.16, freq: 2000, slideTo: 280, type: 'bandpass', q: 2 });
    this.tone({ freq: 300, endFreq: 90, type: 'sawtooth', dur: 0.4, gain: 0.08 });
  }

  emp() {
    this.tone({ freq: 60, endFreq: 900, type: 'sawtooth', dur: 0.5, gain: 0.16, filter: 'lowpass' });
    this.noise({ dur: 0.7, gain: 0.2, freq: 2400, slideTo: 200, type: 'bandpass', q: 1.3 });
    this.tone({ freq: 1400, endFreq: 200, type: 'sine', dur: 0.7, gain: 0.08 });
  }

  relicPickup() {
    const notes = [392, 523.25, 659.25, 783.99];
    notes.forEach((f, i) => {
      this.tone({ freq: f, type: 'triangle', dur: 1.1, gain: 0.075, delay: i * 0.09, dest: this.music });
      this.tone({ freq: f * 2, type: 'sine', dur: 0.7, gain: 0.025, delay: i * 0.09 + 0.02, dest: this.music });
    });
    this.noise({ dur: 0.5, gain: 0.06, freq: 2200, type: 'bandpass', q: 1.5 });
  }

  healthPickup() {
    this.tone({ freq: 330, endFreq: 660, type: 'triangle', dur: 0.35, gain: 0.08 });
    this.tone({ freq: 494, endFreq: 988, type: 'sine', dur: 0.4, gain: 0.05, delay: 0.06 });
  }

  energyPickup() {
    this.tone({ freq: 620, endFreq: 1240, type: 'square', dur: 0.2, gain: 0.04 });
    this.tone({ freq: 930, endFreq: 1860, type: 'sine', dur: 0.3, gain: 0.04, delay: 0.06 });
  }

  shard() {
    this.tone({ freq: 1050 + Math.random() * 300, endFreq: 1600, type: 'sine', dur: 0.09, gain: 0.035 });
  }

  bossRoar() {
    if (!this.ready) return;
    this.tone({ freq: 70, endFreq: 38, type: 'sawtooth', dur: 1.6, gain: 0.24, filter: 'lowpass' });
    this.tone({ freq: 93, endFreq: 52, type: 'square', dur: 1.4, gain: 0.1, filter: 'lowpass' });
    this.noise({ dur: 1.8, gain: 0.16, freq: 520, slideTo: 80, type: 'bandpass', q: 1.1 });
    this.tone({ freq: 1400, endFreq: 700, type: 'sawtooth', dur: 0.9, gain: 0.035, delay: 0.2 });
  }

  bossShoot() {
    this.tone({ freq: 260, endFreq: 70, type: 'sawtooth', dur: 0.35, gain: 0.11 });
    this.noise({ dur: 0.25, gain: 0.1, freq: 1300, slideTo: 220 });
  }

  bossSlam() {
    this.tone({ freq: 55, endFreq: 20, type: 'sine', dur: 0.9, gain: 0.3 });
    this.noise({ dur: 0.7, gain: 0.24, freq: 280, slideTo: 40 });
    this.tone({ freq: 110, endFreq: 40, type: 'square', dur: 0.5, gain: 0.09 });
  }

  bossHit() {
    this.tone({ freq: 320, endFreq: 120, type: 'square', dur: 0.07, gain: 0.05 });
  }

  bossDeath() {
    if (!this.ready) return;
    for (let i = 0; i < 4; i++) {
      setTimeout(() => this.explosion(1.4), i * 240);
    }
    this.tone({ freq: 160, endFreq: 28, type: 'sawtooth', dur: 2.6, gain: 0.16, filter: 'lowpass' });
    this.setBossMode(false);
  }

  playerDeath() {
    this.tone({ freq: 330, endFreq: 40, type: 'sawtooth', dur: 1.1, gain: 0.17, filter: 'lowpass' });
    this.noise({ dur: 1, gain: 0.2, freq: 800, slideTo: 40 });
  }

  victory() {
    const chords = [[261.63, 329.63, 392], [349.23, 440, 523.25], [392, 493.88, 587.33], [523.25, 659.25, 783.99]];
    chords.forEach((chord, i) => {
      chord.forEach((f) => this.tone({ freq: f, type: 'triangle', dur: 1.3, gain: 0.045, delay: i * 0.28, dest: this.music }));
    });
  }

  update(dt) {
    if (!this.ready) return;
    this.ambientTimer = (this.ambientTimer || 0) - dt;
    if (this.ambientTimer <= 0 && !this.bossLayer) {
      this.ambientTimer = 5 + Math.random() * 11;
      const base = 700 + Math.random() * 800;
      this.tone({ freq: base, endFreq: base * 1.2, type: 'sine', dur: 0.5, gain: 0.012, dest: this.music });
      this.tone({ freq: base * 1.5, endFreq: base * 1.1, type: 'sine', dur: 0.4, gain: 0.008, delay: 0.12, dest: this.music });
    }
  }
}

import * as THREE from 'three';
import { clamp, formatTime, padScore } from './utils.js';

const TAU = Math.PI * 2;

export class UI {
  constructor(world, player) {
