  const fx = -Math.sin(this.camYaw);
  const fz = -Math.cos(this.camYaw);
  const rx = Math.cos(this.camYaw);
  const rz = -Math.sin(this.camYaw);
  const base = new THREE.Vector3(
    this.player.position.x + rx * shoulder,
    this.player.position.y + height,
    this.player.position.z + rz * shoulder
  );
  const lookTarget = new THREE.Vector3(
    base.x + fx * ahead,
    base.y + 0.2,
    base.z + fz * ahead
  );
  const cosP = Math.cos(this.camPitch);
  const desired = new THREE.Vector3(
    base.x + Math.sin(this.camYaw) * cosP * dist,
    base.y + Math.sin(this.camPitch) * dist + 0.6,
    base.z + Math.cos(this.camYaw) * cosP * dist
  );
  const minY = this.world.heightAt(desired.x, desired.z) + 1.4;
  if (desired.y < minY) desired.y = minY;

  if (this.introT < 1) {
    this.introT = Math.min(1, this.introT + dt / 2.1);
    const t = smoothstep(0, 1, this.introT);
    this.camPos.lerpVectors(this.introStartPos, desired, t);
    this.camLook.lerpVectors(this.introStartLook, lookTarget, t);
  } else {
    this.camPos.lerp(desired, 1 - Math.exp(-9 * dt));
    this.camLook.lerp(lookTarget, 1 - Math.exp(-7 * dt));
  }

  const shake = this.effects.shake * 0.24 + this.player.cameraShake * 0.16;
  this.camera.position.copy(this.camPos);
  if (shake > 0.001) {
    this.camera.position.x += (Math.random() - 0.5) * shake;
    this.camera.position.y += (Math.random() - 0.5) * shake;
    this.camera.position.z += (Math.random() - 0.5) * shake;
  }
  this.camera.lookAt(this.camLook);
  if (shake > 0.001) this.camera.rotation.z += (Math.random() - 0.5) * shake * 0.004;

  const speedRatio = clamp(Math.abs(this.player.speed) / 48, 0, 1);
  const targetFov = 62 + (isVehicle ? 4 : 0) + speedRatio * 6 + (this.player.boosting ? 3 : 0);
  this.camera.fov = damp(this.camera.fov, targetFov, 3.5, dt);
  this.camera.updateProjectionMatrix();
  this.camera.updateMatrixWorld();
}

